INSERT INTO public.documents (code, slug, title, description, subject, grade, education_level, audience, category_type, file_format, preview_url, curriculum_standard, matrix_notes, textbook_series, status, published_at, internal_notes) VALUES
('TH1-TOAN-01', 'giao-an-cv-2345-toan-1-bo-sach-ket-noi-tri-thuc-voi-cuoc-song-th1-toan-01', 'Giáo án (CV 2345) Toán 1 — Bộ sách Kết nối tri thức với cuộc sống', 'Kế hoạch bài dạy Toán 1 soạn chuẩn 4 bước theo Công văn 2345/BGDĐT-GDTH, tích hợp hình ảnh trực quan và phiếu bài tập phát triển phẩm chất, năng lực.', 'Toán', 'Lớp 1', 'Tiểu học', 'giaovien', 'giaoan', 'DOCX', NULL, 'Giáo án (CV 2345)', 'Phiếu bài tập & hoạt động', 'Kết nối tri thức', 'published', now(), NULL),
('TH1-TV-02', 'ke-hoach-bai-day-tieng-viet-1-theo-cv-2345-bo-sach-chan-troi-sang-tao-th1-tv-02', 'Kế hoạch bài dạy Tiếng Việt 1 theo CV 2345 — Bộ sách Chân trời sáng tạo', 'Giáo án Tiếng Việt 1 phân môn Học vần và Luyện đọc theo chuẩn CV 2345, thiết kế trò chơi ngôn ngữ sinh động, kèm phiếu rèn chữ và đọc hiểu.', 'Tiếng Việt', 'Lớp 1', 'Tiểu học', 'giaovien', 'giaoan', 'DOCX', 'https://drive.google.com/file/d/1nZmAg8-FrKxhI8i8RrxzYDg0GDTdRPkz/view?usp=sharing', 'Giáo án (CV 2345)', 'Kèm slide & phiếu rèn chữ', 'Chân trời sáng tạo', 'published', now(), NULL),
('TH1-ANH-03', 'bo-de-kiem-tra-dinh-ky-tieng-anh-1-theo-thong-tu-27-bo-sach-global-success-th1-anh-03', 'Bộ đề kiểm tra định kỳ Tiếng Anh 1 theo Thông tư 27 (Bộ sách Global Success)', 'Đề kiểm tra giữa kỳ và cuối năm Tiếng Anh 1 đánh giá năng lực ngôn ngữ theo Thông tư 27/2020/TT-BGDĐT, có đầy đủ ma trận và file nghe audio.', 'Tiếng Anh', 'Lớp 1', 'Tiểu học', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Chuẩn Thông tư 27', 'Đầy đủ ma trận & audio', 'Kết nối tri thức', 'published', now(), NULL),
('TH1-TNXH-04', 'giao-an-cv-2345-tu-nhien-va-xa-hoi-1-bo-sach-canh-dieu-th1-tnxh-04', 'Giáo án (CV 2345) Tự nhiên và Xã hội 1 — Bộ sách Cánh Diều', 'Kế hoạch bài dạy TN&XH 1 trọn bộ cả năm theo CV 2345, định hướng giáo dục tích hợp khoa học và đời sống qua các phiếu bài tập trải nghiệm.', 'Tự nhiên và Xã hội', 'Lớp 1', 'Tiểu học', 'giaovien', 'giaoan', 'DOCX', NULL, 'Giáo án (CV 2345)', 'Phiếu trải nghiệm Word', 'Cánh Diều', 'published', now(), NULL),
('TH2-TOAN-05', 'bo-de-kiem-tra-dinh-ky-toan-2-theo-thong-tu-27-bo-sach-canh-dieu-th2-toan-05', 'Bộ đề kiểm tra định kỳ Toán 2 theo Thông tư 27 (Bộ sách Cánh Diều)', 'Đề kiểm tra giữa kỳ 1, kỳ 2 và cuối năm môn Toán 2 có bảng đặc tả ma trận 3 mức độ, bài tập phân hóa theo chuẩn đánh giá học sinh tiểu học.', 'Toán', 'Lớp 2', 'Tiểu học', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Chuẩn Thông tư 27', 'Ma trận 3 mức độ & lời giải', 'Cánh Diều', 'published', now(), NULL),
('TH2-TV-06', 'giao-an-cv-2345-tieng-viet-2-bo-sach-ket-noi-tri-thuc-voi-cuoc-song-th2-tv-06', 'Giáo án (CV 2345) Tiếng Việt 2 — Bộ sách Kết nối tri thức với cuộc sống', 'Kế hoạch bài dạy môn Tiếng Việt 2 trọn bộ 35 tuần theo CV 2345, có ma trận bài dạy, bảng kiểm đánh giá kỹ năng đọc hiểu và viết đoạn văn.', 'Tiếng Việt', 'Lớp 2', 'Tiểu học', 'giaovien', 'giaoan', 'DOCX', NULL, 'Giáo án (CV 2345)', 'Đầy đủ 35 tuần dạy học', 'Kết nối tri thức', 'published', now(), NULL),
('TH2-ANH-07', 'tai-lieu-on-tap-bai-tap-bo-tro-tieng-anh-2-bo-sach-family-and-friends-th2-anh-07', 'Tài liệu ôn tập & Bài tập bổ trợ Tiếng Anh 2 (Bộ sách Family and Friends)', 'Hệ thống từ vựng, mẫu câu và phiếu luyện tập cuối tuần Tiếng Anh 2 thiết kế theo chuẩn GDPT 2018, giúp học sinh củng cố kiến thức vững chắc.', 'Tiếng Anh', 'Lớp 2', 'Tiểu học', 'nguoihoc', 'ontap', 'DOCX', NULL, 'Chuẩn GDPT 2018', 'Phiếu ôn tập & đáp án', 'Chân trời sáng tạo', 'published', now(), NULL),
('TH2-TNXH-08', 'giao-an-cv-2345-tu-nhien-va-xa-hoi-2-bo-sach-chan-troi-sang-tao-th2-tnxh-08', 'Giáo án (CV 2345) Tự nhiên và Xã hội 2 — Bộ sách Chân trời sáng tạo', 'Kế hoạch bài dạy TN&XH 2 bám sát hướng dẫn 2345, hướng dẫn học sinh tìm hiểu về gia đình, nhà trường, thực vật và động vật quanh em.', 'Tự nhiên và Xã hội', 'Lớp 2', 'Tiểu học', 'giaovien', 'giaoan', 'DOCX', NULL, 'Giáo án (CV 2345)', 'Kèm phiếu khảo sát thực hành', 'Chân trời sáng tạo', 'published', now(), NULL),
('TH3-TOAN-09', 'giao-an-cv-2345-toan-3-bo-sach-ket-noi-tri-thuc-voi-cuoc-song-th3-toan-09', 'Giáo án (CV 2345) Toán 3 — Bộ sách Kết nối tri thức với cuộc sống', 'Soạn chi tiết theo CV 2345 các mạch kiến thức: Số học trong phạm vi 100.000, Hình học và đo lường, Một số yếu tố thống kê và xác suất.', 'Toán', 'Lớp 3', 'Tiểu học', 'giaovien', 'giaoan', 'DOCX', NULL, 'Giáo án (CV 2345)', 'Kèm bài tập nâng cao', 'Kết nối tri thức', 'published', now(), NULL),
('TH3-TV-10', 'bo-de-kiem-tra-dinh-ky-tieng-viet-3-theo-thong-tu-27-bo-sach-canh-dieu-th3-tv-10', 'Bộ đề kiểm tra định kỳ Tiếng Việt 3 theo Thông tư 27 (Bộ sách Cánh Diều)', 'Bộ đề kiểm tra định kỳ Tiếng Việt 3 gồm Đọc hiểu (văn bản ngoài SGK) và Luyện viết đoạn văn, có ma trận đề thi và barem điểm chấm chi tiết.', 'Tiếng Việt', 'Lớp 3', 'Tiểu học', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Chuẩn Thông tư 27', 'Ma trận & barem điểm chấm', 'Cánh Diều', 'published', now(), NULL),
('TH3-ANH-11', 'bo-de-kiem-tra-dinh-ky-tieng-anh-3-theo-cau-truc-thong-tu-27-global-success-th3-anh-11', 'Bộ đề kiểm tra định kỳ Tiếng Anh 3 theo cấu trúc Thông tư 27 (Global Success)', 'Hệ thống đề thi giữa kỳ, học kỳ 1 và 2 môn Tiếng Anh 3 thiết kế 4 kỹ năng Nghe - Nói - Đọc - Viết có đáp án và bản đặc tả năng lực.', 'Tiếng Anh', 'Lớp 3', 'Tiểu học', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Chuẩn Thông tư 27', 'Bản đặc tả & audio file', 'Kết nối tri thức', 'published', now(), NULL),
('TH3-TNXH-12', 'ke-hoach-bai-day-cv-2345-tu-nhien-va-xa-hoi-3-bo-sach-canh-dieu-th3-tnxh-12', 'Kế hoạch bài dạy (CV 2345) Tự nhiên và Xã hội 3 — Bộ sách Cánh Diều', 'Giáo án TN&XH 3 theo hướng tiếp cận năng lực giải quyết vấn đề, chuẩn bị chu đáo phiếu quan sát và hướng dẫn hoạt động nhóm cho học sinh.', 'Tự nhiên và Xã hội', 'Lớp 3', 'Tiểu học', 'giaovien', 'giaoan', 'DOCX', NULL, 'Giáo án (CV 2345)', 'Phiếu thảo luận nhóm Word', 'Cánh Diều', 'published', now(), NULL),
('TH4-TOAN-13', 'bo-de-kiem-tra-dinh-ky-toan-4-theo-thong-tu-27-bo-sach-ket-noi-tri-thuc-th4-toan-13', 'Bộ đề kiểm tra định kỳ Toán 4 theo Thông tư 27 (Bộ sách Kết nối tri thức)', 'Hệ thống đề thi giữa kỳ và cuối năm Toán 4 bám sát Thông tư 27 với 3 mức độ nhận thức, có bản đặc tả ma trận đề thi và hướng dẫn chấm.', 'Toán', 'Lớp 4', 'Tiểu học', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Chuẩn Thông tư 27', 'Bản đặc tả & hướng dẫn chấm', 'Kết nối tri thức', 'published', now(), NULL),
('TH4-TV-14', 'giao-an-cv-2345-tieng-viet-4-bo-sach-chan-troi-sang-tao-th4-tv-14', 'Giáo án (CV 2345) Tiếng Việt 4 — Bộ sách Chân trời sáng tạo', 'Kế hoạch bài dạy Tiếng Việt 4 trọn bộ theo CV 2345, định hướng rèn kỹ năng viết bài văn miêu tả và rèn luyện từ và câu theo phương pháp mới.', 'Tiếng Việt', 'Lớp 4', 'Tiểu học', 'giaovien', 'giaoan', 'DOCX', NULL, 'Giáo án (CV 2345)', 'Kèm dàn ý văn mẫu Word', 'Chân trời sáng tạo', 'published', now(), NULL),
('TH4-ANH-15', 'de-cuong-on-tap-bo-de-kiem-tra-tieng-anh-4-bo-sach-canh-dieu-th4-anh-15', 'Đề cương ôn tập & Bộ đề kiểm tra Tiếng Anh 4 (Bộ sách Cánh Diều)', 'Tài liệu ôn tập tổng hợp ngữ pháp, từ vựng theo chủ đề và bộ đề kiểm tra định kỳ Tiếng Anh 4 có bảng phân tích ma trận kỹ năng.', 'Tiếng Anh', 'Lớp 4', 'Tiểu học', 'ca_hai', 'ontap', 'DOCX', NULL, 'Chuẩn Thông tư 27', 'Ma trận & đề cương ôn tập', 'Cánh Diều', 'published', now(), NULL),
('TH4-KH-16', 'giao-an-cv-2345-khoa-hoc-4-bo-sach-ket-noi-tri-thuc-voi-cuoc-song-th4-kh-16', 'Giáo án (CV 2345) Khoa học 4 — Bộ sách Kết nối tri thức với cuộc sống', 'Kế hoạch dạy học môn Khoa học 4 theo CV 2345, thiết kế phiếu thí nghiệm khoa học, hướng dẫn học sinh tìm hiểu về chất, năng lượng và sinh vật.', 'Khoa học', 'Lớp 4', 'Tiểu học', 'giaovien', 'giaoan', 'DOCX', 'https://drive.google.com/file/d/1dFGTOA1ybIrAeYKdqWFphMzyRWnL8N1G/view?usp=sharing', 'Giáo án (CV 2345)', 'Phiếu thí nghiệm trực quan', 'Kết nối tri thức', 'published', now(), NULL),
('TH4-LS&DL-17', 'bo-de-kiem-tra-dinh-ky-lich-su-va-dia-ly-4-co-ma-tran-bo-sach-canh-dieu-th4-ls&dl-17', 'Bộ đề kiểm tra định kỳ Lịch sử và Địa lý 4 có ma trận (Bộ sách Cánh Diều)', 'Bộ đề kiểm tra định kỳ môn Lịch sử và Địa lý 4 gồm trắc nghiệm và tự luận có bản đặc tả ma trận câu hỏi bám sát chuẩn kiến thức kỹ năng.', 'Lịch sử và Địa lý', 'Lớp 4', 'Tiểu học', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Chuẩn Thông tư 27', 'Bản đặc tả & đáp án chi tiết', 'Cánh Diều', 'published', now(), NULL),
('TH5-TOAN-18', 'giao-an-cv-2345-toan-5-bo-sach-ket-noi-tri-thuc-voi-cuoc-song-th5-toan-18', 'Giáo án (CV 2345) Toán 5 — Bộ sách Kết nối tri thức với cuộc sống', 'Kế hoạch bài dạy môn Toán 5 chuẩn CV 2345, trọng tâm kiến thức phân số, số thập phân, hình học không gian và các bài toán chuyển động đều.', 'Toán', 'Lớp 5', 'Tiểu học', 'giaovien', 'giaoan', 'DOCX', NULL, 'Giáo án (CV 2345)', 'Chuyên đề phân dạng bài toán', 'Kết nối tri thức', 'published', now(), NULL),
('TH5-TV-19', 'bo-de-kiem-tra-dinh-ky-tieng-viet-5-theo-thong-tu-27-bo-sach-canh-dieu-th5-tv-19', 'Bộ đề kiểm tra định kỳ Tiếng Việt 5 theo Thông tư 27 (Bộ sách Cánh Diều)', 'Tuyển tập đề kiểm tra giữa kỳ 1, kỳ 2 và đề khảo sát chất lượng cuối năm Tiếng Việt 5 có ma trận và barem chấm chi tiết phần làm văn.', 'Tiếng Việt', 'Lớp 5', 'Tiểu học', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Chuẩn Thông tư 27', 'Ma trận & barem chấm văn', 'Cánh Diều', 'published', now(), NULL),
('TH5-ANH-20', 'bo-de-kiem-tra-dinh-ky-de-thi-vao-6-tieng-anh-5-global-success-th5-anh-20', 'Bộ đề kiểm tra định kỳ & Đề thi vào 6 Tiếng Anh 5 (Global Success)', 'Bộ đề kiểm tra định kỳ môn Tiếng Anh 5 và đề ôn tập khảo sát đầu vào lớp 6 chất lượng cao có đáp án và file nghe chuẩn.', 'Tiếng Anh', 'Lớp 5', 'Tiểu học', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Chuẩn Thông tư 27', 'Đề thi thử & audio nghe', 'Kết nối tri thức', 'published', now(), NULL),
('TH5-KH-21', 'giao-an-cv-2345-khoa-hoc-5-bo-sach-chan-troi-sang-tao-th5-kh-21', 'Giáo án (CV 2345) Khoa học 5 — Bộ sách Chân trời sáng tạo', 'Kế hoạch bài dạy môn Khoa học 5 chuẩn 2345, thiết kế bài giảng gắn liền thực tiễn: sinh sản ở thực vật và động vật, bảo vệ môi trường.', 'Khoa học', 'Lớp 5', 'Tiểu học', 'giaovien', 'giaoan', 'DOCX', NULL, 'Giáo án (CV 2345)', 'Phiếu học tập nghiên cứu', 'Chân trời sáng tạo', 'published', now(), NULL),
('TH5-LS&DL-22', 'bo-de-kiem-tra-dinh-ky-lich-su-va-dia-ly-5-co-ma-tran-bo-sach-kntt-th5-ls&dl-22', 'Bộ đề kiểm tra định kỳ Lịch sử và Địa lý 5 có ma trận (Bộ sách KNTT)', 'Đề kiểm tra định kỳ Lịch sử - Địa lý 5 theo Thông tư 27, đánh giá hiểu biết địa lý các châu lục và các mốc lịch sử hào hùng của dân tộc.', 'Lịch sử và Địa lý', 'Lớp 5', 'Tiểu học', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Chuẩn Thông tư 27', 'Ma trận câu hỏi 3 mức độ', 'Kết nối tri thức', 'published', now(), NULL),
('THCS6-TOAN-23', 'ke-hoach-bai-day-cv-5512-toan-6-bo-sach-ket-noi-tri-thuc-voi-cuoc-song-thcs6-toan-23', 'Kế hoạch bài dạy (CV 5512) Toán 6 — Bộ sách Kết nối tri thức với cuộc sống', 'Giáo án Toán 6 trọn bộ cả năm theo Công văn 5512/BGDĐT-GDTrH: Số tự nhiên, Số nguyên, Phân số, Hình học trực quan và Thống kê xác suất.', 'Toán', 'Lớp 6', 'THCS', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Kèm phiếu bài tập 5512', 'Kết nối tri thức', 'published', now(), NULL),
('THCS6-VAN-24', 'ke-hoach-bai-day-cv-5512-ngu-van-6-bo-sach-canh-dieu-day-du-ca-nam-thcs6-van-24', 'Kế hoạch bài dạy (CV 5512) Ngữ văn 6 — Bộ sách Cánh Diều (Đầy đủ cả năm)', 'Kế hoạch bài dạy Ngữ văn 6 soạn theo cấu trúc 5512, hướng dẫn dạy đọc hiểu theo thể loại truyện đồng thoại, thơ lục bát và viết bài tự sự.', 'Ngữ văn', 'Lớp 6', 'THCS', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Phiếu học tập thể loại', 'Cánh Diều', 'published', now(), NULL),
('THCS6-ANH-25', 'bo-de-kiem-tra-dinh-ky-tieng-anh-6-theo-cau-truc-moi-co-bang-dac-ta-thcs6-anh-25', 'Bộ đề kiểm tra định kỳ Tiếng Anh 6 theo cấu trúc mới có bảng đặc tả', 'Đề kiểm tra giữa kỳ 1, kỳ 2 và cuối học kỳ môn Tiếng Anh 6 theo hướng tiếp cận năng lực, có ma trận câu hỏi và file nghe audio.', 'Tiếng Anh', 'Lớp 6', 'THCS', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Bảng đặc tả & audio file', 'Kết nối tri thức', 'published', now(), NULL),
('THCS6-KHTN-26', 'ke-hoach-bai-day-cv-5512-khoa-hoc-tu-nhien-6-bo-chan-troi-sang-tao-thcs6-khtn-26', 'Kế hoạch bài dạy (CV 5512) Khoa học tự nhiên 6 — Bộ Chân trời sáng tạo', 'Giáo án KHTN 6 tích hợp Vật lý, Hóa học, Sinh học theo chuẩn 5512, thiết kế chi tiết hoạt động khởi động, hình thành kiến thức và luyện tập.', 'Khoa học Tự nhiên', 'Lớp 6', 'THCS', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Phiếu thí nghiệm tích hợp', 'Chân trời sáng tạo', 'published', now(), NULL),
('THCS6-LS&DL-27', 'bo-de-kiem-tra-dinh-ky-lich-su-va-dia-ly-6-co-ma-tran-bo-sach-canh-dieu-thcs6-ls&dl-27', 'Bộ đề kiểm tra định kỳ Lịch sử và Địa lý 6 có ma trận (Bộ sách Cánh Diều)', 'Đề kiểm tra đánh giá định kỳ phân môn Lịch sử và Địa lý 6 theo ma trận công văn chuyên môn, kết hợp câu hỏi trắc nghiệm khách quan và tự luận.', 'Lịch sử và Địa lý', 'Lớp 6', 'THCS', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Ma trận & barem chấm', 'Cánh Diều', 'published', now(), NULL),
('THCS7-TOAN-28', 'bo-de-kiem-tra-dinh-ky-toan-7-theo-cau-truc-moi-trac-nghiem-dung-sai-tra-loi-ngan-thcs7-toan-28', 'Bộ đề kiểm tra định kỳ Toán 7 theo cấu trúc mới (Trắc nghiệm Đúng/Sai & Trả lời ngắn)', 'Đề kiểm tra định kỳ môn Toán lớp 7 theo định dạng mới của Bộ GD&ĐT gồm trắc nghiệm 4 lựa chọn, trắc nghiệm đúng sai và tự luận có ma trận chi tiết.', 'Toán', 'Lớp 7', 'THCS', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Đầy đủ ma trận & lời giải', 'Kết nối tri thức', 'published', now(), NULL),
('THCS7-VAN-29', 'ke-hoach-bai-day-cv-5512-ngu-van-7-bo-sach-ket-noi-tri-thuc-voi-cuoc-song-thcs7-van-29', 'Kế hoạch bài dạy (CV 5512) Ngữ văn 7 — Bộ sách Kết nối tri thức với cuộc sống', 'Giáo án Ngữ văn 7 soạn chuẩn 5512 định hướng phát triển năng lực, tập trung vào kỹ năng đọc hiểu văn bản nghị luận, thơ 4 chữ, 5 chữ và viết bài văn biểu cảm.', 'Ngữ văn', 'Lớp 7', 'THCS', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Phiếu rèn kỹ năng viết', 'Kết nối tri thức', 'published', now(), NULL),
('THCS7-ANH-30', 'de-cuong-on-tap-bo-de-kiem-tra-dinh-ky-tieng-anh-7-global-success-thcs7-anh-30', 'Đề cương ôn tập & Bộ đề kiểm tra định kỳ Tiếng Anh 7 (Global Success)', 'Tài liệu ôn tập tổng hợp ngữ pháp theo Unit và bộ đề kiểm tra giữa kỳ, học kỳ Tiếng Anh 7 có ma trận và file nghe audio.', 'Tiếng Anh', 'Lớp 7', 'THCS', 'ca_hai', 'ontap', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Ma trận & đề thi kèm audio', 'Kết nối tri thức', 'published', now(), NULL),
('THCS7-KHTN-31', 'ke-hoach-bai-day-cv-5512-khoa-hoc-tu-nhien-7-bo-sach-canh-dieu-thcs7-khtn-31', 'Kế hoạch bài dạy (CV 5512) Khoa học tự nhiên 7 — Bộ sách Cánh Diều', 'Kế hoạch bài dạy KHTN 7 theo cấu trúc 5512: các chủ đề Nguyên tử, Bảng tuần hoàn, Tốc độ, Âm thanh, Ánh sáng và Trao đổi chất ở sinh vật.', 'Khoa học Tự nhiên', 'Lớp 7', 'THCS', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Phiếu học tập 4 hoạt động', 'Cánh Diều', 'published', now(), NULL),
('THCS7-LS&DL-32', 'bo-de-kiem-tra-dinh-ky-lich-su-va-dia-ly-7-co-ma-tran-chan-troi-sang-tao-thcs7-ls&dl-32', 'Bộ đề kiểm tra định kỳ Lịch sử và Địa lý 7 có ma trận (Chân trời sáng tạo)', 'Bộ đề kiểm tra định kỳ Lịch sử và Địa lý 7 bám sát công văn chuyên môn, kiểm tra kiến thức lịch sử phong kiến châu Âu và địa lý các châu lục.', 'Lịch sử và Địa lý', 'Lớp 7', 'THCS', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Ma trận & bản đặc tả', 'Chân trời sáng tạo', 'published', now(), NULL),
('THCS8-TOAN-33', 'bo-de-kiem-tra-dinh-ky-toan-8-theo-cau-truc-moi-bo-sach-canh-dieu-thcs8-toan-33', 'Bộ đề kiểm tra định kỳ Toán 8 theo cấu trúc mới (Bộ sách Cánh Diều)', 'Hệ thống đề kiểm tra đánh giá năng lực Toán lớp 8 gồm trắc nghiệm nhiều lựa chọn, đúng sai và tự luận phân loại học sinh có đầy đủ ma trận.', 'Toán', 'Lớp 8', 'THCS', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Đầy đủ ma trận & đáp án', 'Cánh Diều', 'published', now(), NULL),
('THCS8-VAN-34', 'ke-hoach-bai-day-cv-5512-ngu-van-8-bo-sach-chan-troi-sang-tao-thcs8-van-34', 'Kế hoạch bài dạy (CV 5512) Ngữ văn 8 — Bộ sách Chân trời sáng tạo', 'Kế hoạch bài dạy môn Ngữ văn 8 soạn theo hướng dẫn 5512, tích hợp đọc hiểu văn học hiện thực, thơ tự do và rèn kỹ năng viết bài văn nghị luận xã hội.', 'Ngữ văn', 'Lớp 8', 'THCS', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Phụ lục dàn ý văn mẫu', 'Chân trời sáng tạo', 'published', now(), NULL),
('THCS8-ANH-35', 'bo-de-kiem-tra-dinh-ky-tieng-anh-8-theo-cau-truc-moi-co-bang-dac-ta-ma-tran-thcs8-anh-35', 'Bộ đề kiểm tra định kỳ Tiếng Anh 8 theo cấu trúc mới có bảng đặc tả ma trận', 'Hệ thống đề thi giữa kỳ, học kỳ 1 và học kỳ 2 môn Tiếng Anh 8 bám sát chương trình GDPT 2018, có ma trận và file audio chuẩn.', 'Tiếng Anh', 'Lớp 8', 'THCS', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Bản đặc tả & audio file', 'Kết nối tri thức', 'published', now(), NULL),
('THCS8-KHTN-36', 'ke-hoach-bai-day-cv-5512-khoa-hoc-tu-nhien-8-bo-ket-noi-tri-thuc-thcs8-khtn-36', 'Kế hoạch bài dạy (CV 5512) Khoa học tự nhiên 8 — Bộ Kết nối tri thức', 'Giáo án KHTN 8 soạn chuẩn 5512: Phản ứng hóa học, Acid - Base, Áp suất, Lực đẩy Archimedes, Cơ thể người và Hệ sinh thái.', 'Khoa học Tự nhiên', 'Lớp 8', 'THCS', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Phiếu thực hành thí nghiệm', 'Kết nối tri thức', 'published', now(), NULL),
('THCS8-LS&DL-37', 'ke-hoach-bai-day-cv-5512-lich-su-va-dia-ly-8-bo-sach-canh-dieu-thcs8-ls&dl-37', 'Kế hoạch bài dạy (CV 5512) Lịch sử và Địa lý 8 — Bộ sách Cánh Diều', 'Kế hoạch bài dạy phân môn Lịch sử và Địa lý 8 theo CV 5512: Cách mạng tư sản, Lịch sử Việt Nam thời Nguyễn, Địa lý tự nhiên và khoáng sản VN.', 'Lịch sử và Địa lý', 'Lớp 8', 'THCS', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Lược đồ & sơ đồ tư duy', 'Cánh Diều', 'published', now(), NULL),
('THCS9-TOAN-38', 'tuyen-tap-de-kiem-tra-de-thi-vao-10-toan-9-cau-truc-moi-co-ma-tran-thcs9-toan-38', 'Tuyển tập đề kiểm tra & Đề thi vào 10 Toán 9 cấu trúc mới (Có ma trận)', 'Bộ đề kiểm tra định kỳ Toán 9 và 20 đề ôn thi tuyển sinh vào lớp 10 theo định dạng cấu trúc đánh giá năng lực mới của các Sở GD&ĐT.', 'Toán', 'Lớp 9', 'THCS', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc định dạng mới', 'Bản đặc tả & lời giải chi tiết', 'Kết nối tri thức', 'published', now(), NULL),
('THCS9-VAN-39', 'ke-hoach-bai-day-cv-5512-ngu-van-9-bo-sach-ket-noi-tri-thuc-voi-cuoc-song-thcs9-van-39', 'Kế hoạch bài dạy (CV 5512) Ngữ văn 9 — Bộ sách Kết nối tri thức với cuộc sống', 'Giáo án Ngữ văn 9 trọn bộ cả năm theo CV 5512, tích hợp chuyên đề ôn thi vào lớp 10: Nghị luận xã hội và Nghị luận văn học theo chương trình mới.', 'Ngữ văn', 'Lớp 9', 'THCS', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Chuyên đề ôn thi vào 10', 'Kết nối tri thức', 'published', now(), NULL),
('THCS9-ANH-40', 'bo-de-thi-thu-tuyen-sinh-vao-lop-10-mon-tieng-anh-theo-cau-truc-moi-thcs9-anh-40', 'Bộ đề thi thử tuyển sinh vào lớp 10 môn Tiếng Anh theo cấu trúc mới', 'Bộ đề ôn thi tuyển sinh vào 10 Tiếng Anh bám sát cấu trúc mới các tỉnh thành, bao gồm trắc nghiệm ngữ âm, từ vựng, đọc hiểu và viết lại câu.', 'Tiếng Anh', 'Lớp 9', 'THCS', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Đáp án & giải thích chi tiết', 'Cánh Diều', 'published', now(), NULL),
