('THCS9-LS&DL-42', 'bo-de-kiem-tra-dinh-ky-lich-su-va-dia-ly-9-co-ma-tran-bo-sach-kntt-thcs9-ls&dl-42', 'Bộ đề kiểm tra định kỳ Lịch sử và Địa lý 9 có ma trận (Bộ sách KNTT)', 'Đề kiểm tra giữa kỳ và cuối năm Lịch sử - Địa lý 9 theo ma trận chuẩn, bao gồm Lịch sử Việt Nam hiện đại và Địa lý kinh tế các vùng.', 'Lịch sử và Địa lý', 'Lớp 9', 'THCS', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Đầy đủ ma trận & đáp án', 'Kết nối tri thức', 'published', now(), NULL),
('THPT10-TOAN-43', 'ke-hoach-bai-day-cv-5512-toan-10-bo-sach-ket-noi-tri-thuc-voi-cuoc-song-thpt10-toan-43', 'Kế hoạch bài dạy (CV 5512) Toán 10 — Bộ sách Kết nối tri thức với cuộc sống', 'Giáo án Toán 10 soạn chuẩn 5512 trọn bộ: Mệnh đề, Tập hợp, Hàm số bậc hai, Vector, Phương pháp tọa độ và Thống kê xác suất.', 'Toán', 'Lớp 10', 'THPT', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Kèm chuyên đề học tập', 'Kết nối tri thức', 'published', now(), NULL),
