('THPT11-VAN-52', 'ke-hoach-bai-day-cv-5512-ngu-van-11-bo-sach-chan-troi-sang-tao-thpt11-van-52', 'Kế hoạch bài dạy (CV 5512) Ngữ văn 11 — Bộ sách Chân trời sáng tạo', 'Kế hoạch bài dạy Ngữ văn 11 theo CV 5512: Thơ lãng mạn, Thơ mới, Truyện ngắn hiện thực phê phán, Bi kịch và Rèn luyện viết bài văn nghị luận xã hội.', 'Ngữ văn', 'Lớp 11', 'THPT', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Phụ lục văn bản ngoài SGK', 'Chân trời sáng tạo', 'published', now(), NULL),
('THPT11-ANH-53', 'bo-de-kiem-tra-dinh-ky-tieng-anh-11-theo-cau-truc-moi-bo-sach-global-success-thpt11-anh-53', 'Bộ đề kiểm tra định kỳ Tiếng Anh 11 theo cấu trúc mới (Bộ sách Global Success)', 'Đề kiểm tra giữa kỳ, cuối kỳ Tiếng Anh 11 biên soạn theo định dạng đánh giá năng lực của Bộ GD&ĐT có đáp án, transcript và file nghe audio.', 'Tiếng Anh', 'Lớp 11', 'THPT', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Bản đặc tả & audio transcript', 'Kết nối tri thức', 'published', now(), NULL),
('THPT11-LY-54', 'ke-hoach-bai-day-cv-5512-vat-ly-11-bo-sach-ket-noi-tri-thuc-voi-cuoc-song-thpt11-ly-54', 'Kế hoạch bài dạy (CV 5512) Vật lý 11 — Bộ sách Kết nối tri thức với cuộc sống', 'Giáo án Vật lý 11 trọn bộ cả năm các chuyên đề Dao động, Sóng, Điện trường và Dòng điện không đổi bám sát hướng dẫn 5512 của Bộ GD&ĐT.', 'Vật lý', 'Lớp 11', 'THPT', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Phiếu học tập 100% Word', 'Kết nối tri thức', 'published', now(), NULL),
('THPT11-HOA-55', 'bo-de-kiem-tra-dinh-ky-hoa-hoc-11-theo-cau-truc-moi-trac-nghiem-dung-sai-tra-loi-ngan-thpt11-hoa-55', 'Bộ đề kiểm tra định kỳ Hóa học 11 theo cấu trúc mới (Trắc nghiệm Đúng/Sai, trả lời ngắn)', 'Ngân hàng đề kiểm tra Hóa học 11 phần Cân bằng hóa học, Nitrogen - Sulfur, Hợp chất hữu cơ và Hydrocarbon có ma trận và bản đặc tả chi tiết.', 'Hóa học', 'Lớp 11', 'THPT', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Đầy đủ ma trận & lời giải', 'Cánh Diều', 'published', now(), NULL),
('THPT11-SINH-56', 'ngan-hang-cau-hoi-trac-nghiem-dung-sai-sinh-hoc-11-phan-dang-bam-sat-cv-5512-thpt11-sinh-56', 'Ngân hàng câu hỏi trắc nghiệm Đúng/Sai Sinh học 11 phân dạng bám sát CV 5512', 'Hệ thống câu hỏi trắc nghiệm Sinh học 11 phần Sinh lý thực vật và động vật (Trao đổi chất, Cảm ứng, Sinh trưởng và Sinh sản) có đáp án chi tiết.', 'Sinh học', 'Lớp 11', 'THPT', 'nguoihoc', 'chuyende', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Lời giải chi tiết 100% Word', 'Chân trời sáng tạo', 'published', now(), NULL),
('THPT11-SU-57', 'ke-hoach-bai-day-cv-5512-lich-su-11-bo-sach-canh-dieu-thpt11-su-57', 'Kế hoạch bài dạy (CV 5512) Lịch sử 11 — Bộ sách Cánh Diều', 'Giáo án Lịch sử 11 theo chuẩn 5512: Cách mạng tư sản, Quá trình mở rộng xâm lược thuộc địa, Chiến tranh bảo vệ Tổ quốc và công cuộc Đổi mới ở VN.', 'Lịch sử', 'Lớp 11', 'THPT', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Tư liệu lịch sử & câu hỏi', 'Cánh Diều', 'published', now(), NULL),
('THPT11-DIA-58', 'bo-de-kiem-tra-dinh-ky-dia-ly-11-theo-cau-truc-moi-co-ma-tran-bo-sach-kntt-thpt11-dia-58', 'Bộ đề kiểm tra định kỳ Địa lý 11 theo cấu trúc mới có ma trận (Bộ sách KNTT)', 'Đề kiểm tra môn Địa lý 11 theo định dạng trắc nghiệm Đúng/Sai và nhiều lựa chọn: Kinh tế xã hội thế giới, Hoa Kỳ, Liên bang Nga, Nhật Bản, Trung Quốc.', 'Địa lý', 'Lớp 11', 'THPT', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Đầy đủ ma trận & đáp án', 'Kết nối tri thức', 'published', now(), NULL),
('THPT12-TOAN-59', 'bo-de-kiem-tra-dinh-ky-de-thi-thu-tot-nghiep-thpt-toan-12-cau-truc-moi-thpt12-toan-59', 'Bộ đề kiểm tra định kỳ & Đề thi thử Tốt nghiệp THPT Toán 12 cấu trúc mới', 'Tuyển tập 25 đề thi chuẩn định dạng mới của Bộ GD&ĐT (Phần 1: Trắc nghiệm 4 lựa chọn, Phần 2: Trắc nghiệm Đúng/Sai, Phần 3: Trả lời ngắn điền số).', 'Toán', 'Lớp 12', 'THPT', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc định dạng mới 2025', 'Đầy đủ ma trận, đặc tả & giải', 'Kết nối tri thức', 'published', now(), NULL),
('THPT12-VAN-60', 'ke-hoach-bai-day-cv-5512-ngu-van-12-bo-sach-chan-troi-sang-tao-thpt12-van-60', 'Kế hoạch bài dạy (CV 5512) Ngữ văn 12 — Bộ sách Chân trời sáng tạo', 'Giáo án Ngữ văn 12 soạn theo hướng tiếp cận thể loại và phát triển năng lực đọc hiểu văn bản hiện đại, rèn kỹ năng viết bài văn nghị luận xã hội/văn học.', 'Ngữ văn', 'Lớp 12', 'THPT', 'giaovien', 'giaoan', 'DOCX', NULL, 'Kế hoạch bài dạy (CV 5512)', 'Phụ lục đề thi thử TN THPT', 'Chân trời sáng tạo', 'published', now(), NULL),
('THPT12-ANH-61', 'bo-de-kiem-tra-dinh-ky-on-thi-tot-nghiep-thpt-tieng-anh-12-global-success-thpt12-anh-61', 'Bộ đề kiểm tra định kỳ & Ôn thi tốt nghiệp THPT Tiếng Anh 12 (Global Success)', 'Tuyển tập đề kiểm tra giữa kỳ, học kỳ và 30 đề thi thử chuẩn cấu trúc mới của Bộ GD&ĐT có đáp án chi tiết và giải thích ngữ pháp cặn kẽ.', 'Tiếng Anh', 'Lớp 12', 'THPT', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Giải thích chi tiết 100%', 'Kết nối tri thức', 'published', now(), NULL),
('THPT12-LY-62', 'ngan-hang-cau-hoi-trac-nghiem-dung-sai-tra-loi-ngan-vat-ly-12-bo-sach-canh-dieu-thpt12-ly-62', 'Ngân hàng câu hỏi trắc nghiệm Đúng/Sai & Trả lời ngắn Vật lý 12 — Bộ sách Cánh Diều', 'Tài liệu ôn tập phân dạng Vật lý nhiệt, Khí lý tưởng, Từ trường và Vật lý hạt nhân bám sát cấu trúc đề thi Tốt nghiệp THPT mới nhất.', 'Vật lý', 'Lớp 12', 'THPT', 'nguoihoc', 'chuyende', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Phương pháp giải nhanh & đáp án', 'Cánh Diều', 'published', now(), NULL),
('THPT12-HOA-63', 'bo-de-kiem-tra-dinh-ky-hoa-hoc-12-theo-cau-truc-moi-trac-nghiem-dung-sai-tra-loi-ngan-thpt12-hoa-63', 'Bộ đề kiểm tra định kỳ Hóa học 12 theo cấu trúc mới (Trắc nghiệm Đúng/Sai, trả lời ngắn)', 'Hệ thống đề kiểm tra định kỳ Hóa học 12 phần Este-Lipit, Carbohydrate, Hợp chất chứa Nitơ, Polime và Kim loại chuyển tiếp đầy đủ ma trận.', 'Hóa học', 'Lớp 12', 'THPT', 'ca_hai', 'dekiemtra', 'DOCX', NULL, 'Cấu trúc trắc nghiệm mới', 'Đầy đủ ma trận & lời giải', 'Kết nối tri thức', 'published', now(), NULL),
